  if (age < 0 || age > 120) stop("age must be between 0 and 120")
  if (age >= 18) "adult" else "young"
}

fine <- function(days_late) {
  if (is.na(days_late)) return(0)
  days_late * 0.25
}

percent <- function(part, whole) {
  stopifnot(is.numeric(part), is.numeric(whole), whole > 0)
  part / whole * 100
}

speed <- function(km, minutes) {
  if (minutes < 1) warning("very short trip")
  km / (minutes / 60)
}

grade <- function(score) {
  if (is.na(score)) return(NA)
  if (score < 0 || score > 100) stop("score must be between 0 and 100")
  if (score >= 50) "pass" else "fail"
}

safe_divide <- function(a, b) {
  stopifnot(is.numeric(a), is.numeric(b))
  if (b == 0) {
    warning("dividing by zero")
    return(NA)
  }
  a / b
}

